#!/bin/sh
# THIS IS A STUB - NOT INTENDED AS FUNCTIONAL - NA # #
echo "N/A on Linux"

from __future__ import print_function, unicode_literals
import sys
import os
import subprocess
import traceback
try:
    import tanium
except ImportError as e:
	emsg = 'Error locating necessary files. Ensure IC-Python is imported and deployed.'
	sys.exit(emsg)

__author__ = 'Tanium'
__content_name__ = 'SEP Client IPS Revision'
__version__ = '1.0.1.0000'


def get_platform():
    return sys.platform


def mac_sep_ipsrev():
    fIpsRevInfo = "/Library/Application Support/Symantec/Silo/NFM/Definitions/symcdata/vulnprotectiondefs/definfo.dat"
    if os.path.exists(fIpsRevInfo):
        fIpsDat = open(fIpsRevInfo, "r")
        for line in fIpsDat.readlines():
            if "CurDefs=" in line:
                sIpsRev = line.rpartition('=')[-1].rstrip('\n')
                return sIpsRev
                fIpsDat.close()
                break
    else:
        return "Not Installed"


def sensor_main():
    if get_platform() == 'darwin':
        return mac_sep_ipsrev()
    else:
        return "Unsupported platform"


if __name__ == '__main__':
    try:
        r = sensor_main()
    except Exception as e:
        r = traceback.format_exc().replace('\n', '->')
    try:
        tanium.results.add(r)
    except (AttributeError, NameError):
        print(r)

